import { forwardRef, useCallback, useRef } from 'react'
import DynamicForm from '../../../../../../../components/DynamicForm'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import { getVehicleModificationForm } from '../../constants/index'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'

function VehicleModificationPhotos ({ accessories = [], onChange = () => {} }, vehicleModRef) {
  const that = useRef({
    accessories: [
      ...accessories
    ]
  })

  const handleChange = useCallback((data) => {
    for (const key in data) {
      const accKey = parseInt(key.split('_')[2])
      that.current.accessories[accKey].img = data[key]
    }
    onChange({
      accessories: that.current.accessories
    })
  }, [onChange])

  return (
    <>
      <CustomText
        color={AgentColorPallette.black}
        size='1em'
        top='1.2em'
        bottom='0.5em'
        weight={700}
      >
        {LANG_STRINGS.vehicleModificationPhotos}
      </CustomText>
      <DynamicForm
        form={getVehicleModificationForm(accessories)}
        ref={vehicleModRef}
        onChange={handleChange}
      />
    </>
  )
}

export default forwardRef(VehicleModificationPhotos)
