import { useCallback, useEffect, useRef, useState, useMemo } from 'react'
import { clone } from 'lodash'
import moment from 'moment'
import {
  useLoaderContextValue,
  useErrorContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import { Container, CustomText } from '../../../../../../components'
import PolicyStepsHeader from '../../../../../../components/PolicyStepsHeader'
import { LANG_STRINGS } from '../../../../../../lang'
import { POLICY_STEPS } from '../../../constants'
import {
  useGetDraftQuoteDetails,
  useUpdateDraftQuote,
  useValidatePolicyData,
} from '../../../state/hooks/usePolicyState'
import { MVVehicleFormStyle, ButtonContainer, PageContainer } from './index.style'

import VehicleDetails from '../components/VehicleDetails/index'
import VehiclePhotos from '../components/VehiclePhotos'
import VehicleModificationPhotos from '../components/VehicleModificationPhoto'
import VehicleDamageSection from '../components/VehicleDamageSection'
import { getDisabledFields, mappedVehicleDataToForm } from '../constants/index'
import QuoteSaveConfirmModal from '../../../../../../components/QuoteSaveConfirmModal'
import BottomSheetVehicleConflictData from '../components/BottomSheetVehicleConflictData'
import { useBackButton } from '../../../../../../state/commonState/hooks/useBackButton'
import { checkValidateStartDate } from '../../../../../../helpers/utility'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import { typeValid } from '../../../../../../helpers/validations'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import Button from '../../../../../../components/Button/index'
import FixedTab from '../../MVPolicyCustomerData/components/FixedTab'
import { CAR_ICON } from '../../../../../../images'
import { useOcrStnkService } from '../hooks/useOcrStnkService'
import { MV_RENEWAL_STATUS, NEW_PURCHASE } from '../../../../../../constants/pkgCode'

function MVVehicleFormContainer({ match, history }) {
  const [
    {
      DRAFT_QUOTATIONS_DETAILS_LOADER,
      UPDATE_DRAFT_QUOTATION_LOADER,
      POST_DRAFT_POLICY_OCR_LOADER,
    },
  ] = useLoaderContextValue()
  const [{ draftQuotationsDetailsData = {} }, getDraftQuoteDetailsReq] = useGetDraftQuoteDetails()
  const [, updateDraftQuoteReq] = useUpdateDraftQuote()
  const [{ updateDraftQuotationStatus, draftQuotationsDetailsStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [enableSave, setEnableSave] = useState(false)
  const [showQuoteConfirm, setShowQuoteConfirm] = useState(false)
  const [showConflictBottomSheet, setShowConflictBottomSheet] = useState(false)
  const [isBackToMVForm, setIsBackToMVForm] = useState(false)
  const [hasValidationError, setHasValidationError] = useState(false)

  const vehicleDetailRef = useRef()
  const vehiclePhotosRef = useRef()
  const vehicleModPhotosRef = useRef()
  const vehicleDamageRef = useRef()
  const updateDraftTimer = useRef()
  const savedDraftData = useRef({})

  const [render, setRender] = useState(1)

  const { initiateValidateReq: validatePolicyDataReq, isLoader: isChassisValidating } =
    useValidatePolicyData({
      onCall: (data = {}) => {
        if (data.error) {
          setHasValidationError(true)
          ShowSnackbar.error({
            visible: true,
            text: LANG_STRINGS.chassisNumberPolicyAlreadyExist,
          })
        } else if (!data.isRequestPending) {
          setHasValidationError(false)
        }
      },
      errorMsg: LANG_STRINGS.chassisNumberPolicyAlreadyExist,
    })

  const that = useRef({
    formData: { images: {} },
    draftQuoteId: match?.params?.draftQuoteId,
    renewalOrgPolicyId: match?.params?.orgPolicyId,
  })
  const addBackEventListener = useBackButton()

  const handleErrorOcr = () => {
    const isRenewal =
      draftQuotationsDetailsData?.policy_details?.renewal_status === MV_RENEWAL_STATUS.RENEWAL

    let payload = {}

    if (!isRenewal) {
      payload = {
        chasis_number: '',
        machine_number: '',
        color: '',
        plate_number: '',
        back_plate: '',
        vehicle_plate_no: '',
      }
    }
    handleSaveDraft(
      {
        ...payload,
        stnk_use_ocr: false,
      },
      50
    )
  }

  const handleSaveDraftStnk = (data) => {
    // handle the chassis validations
    const params = draftQuotationsDetailsData?.policy_details?.package_data?.pre_validate_params
    if (params) {
      validatePolicyDataReq({
        policy: {
          ...draftQuotationsDetailsData?.policy_details,
          reference_id: draftQuotationsDetailsData?.id,
          chasis_number: data.chassis_number,
        },
        preValidateData: params,
      })
    }

    handleSaveDraft(
      {
        chasis_number: data.chassis_number,
        machine_number: data.machine_number,
        color: data.color,
        plate_number: data.license_plate.number,
        back_plate: data.license_plate.code_end,
        vehicle_plate_no: `${data.license_plate.number}${data.license_plate.code_end}`,
        stnk_use_ocr: true,
      },
      50
    )
  }

  const { handleStnkOcr, stnkOcrData, ocrDisabledFields, isOcrStnkComplete, conflictData } =
    useOcrStnkService({
      draftId: that.current.draftQuoteId,
      handleErrorOcr,
      setShowConflictModal: setShowConflictBottomSheet,
      policyDetailData: draftQuotationsDetailsData?.policy_details,
      handleSaveDraftStnk,
    })

  const disabledFields = useMemo(() => {
    const flowFields = getDisabledFields(
      draftQuotationsDetailsData?.policy_details?.purchase_renew_flow
    )

    const ocrFields =
      draftQuotationsDetailsData?.policy_details?.stnk_url || isOcrStnkComplete
        ? []
        : ocrDisabledFields

    return [...flowFields, ...ocrFields]
  }, [
    draftQuotationsDetailsData?.policy_details?.purchase_renew_flow,
    draftQuotationsDetailsData?.policy_details?.stnk_url,
    ocrDisabledFields,
    isOcrStnkComplete,
  ])

  useEffect(() => {
    getDraftQuoteDetailsReq({ draftQuoteId: that.current.draftQuoteId })
  }, [getDraftQuoteDetailsReq])

  useEffect(() => {
    if (draftQuotationsDetailsData?.policy_details?.package_code && !that.current.removeEvent) {
      that.current.removeEvent = addBackEventListener({
        section: 'insured_object',
        draftId: draftQuotationsDetailsData.id,
      })
      that.current.formData = mappedVehicleDataToForm(draftQuotationsDetailsData.policy_details)

      // Re-validate chassis number on mount if it exists
      const chassisNumber = draftQuotationsDetailsData?.policy_details?.chasis_number
      const params = draftQuotationsDetailsData?.policy_details?.package_data?.pre_validate_params

      if (chassisNumber && params && typeValid('chasis_number', chassisNumber)) {
        validatePolicyDataReq({
          policy: {
            ...draftQuotationsDetailsData?.policy_details,
            reference_id: draftQuotationsDetailsData?.id,
            chasis_number: chassisNumber,
          },
          preValidateData: params,
        })
      }
    }
  }, [draftQuotationsDetailsData, addBackEventListener, validatePolicyDataReq])

  useEffect(() => {
    if (draftQuotationsDetailsStatus === 'success') {
      if (!checkValidateStartDate(draftQuotationsDetailsData?.policy_details?.start_date)) {
        ShowSnackbar.success({
          visible: true,
          text: LANG_STRINGS.policyStartDateHasBeenChangedToCurrent,
        })
        savedDraftData.current.start_date = moment().format('YYYY-MM-DD')
        updateDraftQuoteReq({
          body: {
            section: 'insured_object',
            sub_section: 'stnk_url',
            data: {
              ...draftQuotationsDetailsData?.policy_details,
              start_date: moment().format('YYYY-MM-DD'),
            },
          },
          draftQuoteId: that.current.draftQuoteId,
        })
      }
      setRender((prev) => prev + 1)
      resetError(['draftQuotationsDetailsStatus'])
    }
  }, [draftQuotationsDetailsStatus, resetError, draftQuotationsDetailsData, updateDraftQuoteReq])

  useEffect(() => {
    if (updateDraftQuotationStatus === 'success') {
      // show loader only when click on buy
      if (that.current.isSubmitCall) {
        that.current.isSubmitCall = false
        history.push({
          pathname: `/motor_vehicle/customer/data/form/${that.current.draftQuoteId}`,
          state: {
            from: window.location.pathname,
          },
        })
      } else if (that.current.isChangePkg) {
        resetError(['updateDraftQuotationStatus'])
        history.push(`/motor_vehicle/packages/details/v2/${that.current.draftQuoteId}`)
        return
      } else if (that.current.isSaveClick) {
        that.current.isSaveClick = false
        setEnableSave(false)
        setShowQuoteConfirm(true)
      }
      resetError(['updateDraftQuotationStatus'])
    }
  }, [updateDraftQuotationStatus, resetError, history])

  const handleSaveDraft = useCallback(
    (extraData = {}, timer, subSection) => {
      savedDraftData.current = {
        ...draftQuotationsDetailsData.policy_details,
        ...savedDraftData.current,
        ...extraData,
      }
      if (updateDraftTimer.current) {
        clearTimeout(updateDraftTimer.current)
        updateDraftTimer.current = ''
      }
      setEnableSave(true)
      that.current.subSection = subSection || that.current.subSection
      updateDraftTimer.current = setTimeout(() => {
        updateDraftQuoteReq({
          body: {
            section: that.current.isSubmitCall ? 'customer_data' : 'insured_object',
            sub_section: that.current.isSubmitCall ? 'customer_document' : that.current.subSection,
            data: savedDraftData.current,
          },
          draftQuoteId: that.current.draftQuoteId,
        })
      }, timer || 3000)
    },
    [updateDraftQuoteReq, draftQuotationsDetailsData]
  )

  const handleSubmit = useCallback(
    (e, isEditChassis) => {
      const vehicleDetails = vehicleDetailRef.current.validateFormValues()
      const vehiclePhotos = vehiclePhotosRef.current.validateFormValues()
      const vehicleDamages = vehicleDamageRef.current?.validateFormValues()
      const vehicleModifications =
        vehicleModPhotosRef.current && vehicleModPhotosRef.current.validateFormValues()

      if (vehicleModPhotosRef.current && !vehicleModifications) {
        return
      }

      if (that.current.formData.stnk_url && vehicleDetails && vehiclePhotos) {
        if (vehicleDamageRef.current && !vehicleDamages) {
          return
        }

        that.current.isSubmitCall = !isEditChassis
        handleSaveDraft(clone(that.current.formData), 1)
        return that.current.formData
      }
    },
    [draftQuotationsDetailsData?.policy_details, handleSaveDraft]
  )

  const handleChanges = useCallback(
    (data, section) => {
      // do ocr stnk
      if (section === 'vehicle_detail_object') {
        if (Object.keys(data).includes('stnk_url')) {
          if (data.stnk_url) {
            // dont trigger when renewal
            if (
              ![MV_RENEWAL_STATUS.RENEWAL, MV_RENEWAL_STATUS.REACTIVATION].includes(
                draftQuotationsDetailsData?.policy_details?.renewal_status
              )
            ) {
              handleStnkOcr(data.stnk_url)
            }
          } else {
            // not trigger update when stnk_url is empty
            return
          }
        }
      }
      // Handle field-specific actions
      Object.keys(data).forEach((key) => {
        switch (key) {
          case 'plate_number':
          case 'back_plate':
            data.vehicle_plate_no = [data.plate_number, data.back_plate].join('')
            break
          default:
            break
        }
      })

      that.current.formData = {
        ...that.current.formData,
        ...data,
      }

      if (data.chasis_number && typeValid('chasis_number', data.chasis_number)) {
        // handle the chassis validations
        const params = draftQuotationsDetailsData?.policy_details?.package_data?.pre_validate_params
        if (params) {
          validatePolicyDataReq({
            policy: {
              ...draftQuotationsDetailsData?.policy_details,
              reference_id: draftQuotationsDetailsData?.id,
              chasis_number: data.chasis_number,
            },
            preValidateData: params,
          })
        }
      } else if (data.chasis_number && !typeValid('chasis_number', data.chasis_number)) {
        return
      }

      if (data.machine_number && !typeValid('machine_number', data.machine_number)) {
        return
      }
      handleSaveDraft({ ...data }, 5000, section)
    },
    [
      handleSaveDraft,
      handleStnkOcr,
      draftQuotationsDetailsData?.policy_details,
      draftQuotationsDetailsData?.id,
      validatePolicyDataReq,
    ]
  )

  const handleSaveClick = useCallback(() => {
    that.current.isSaveClick = true
    handleSaveDraft({}, 1, that.current.subSection)
  }, [handleSaveDraft])

  const handleUseOldData = useCallback(() => {
    setShowConflictBottomSheet(false)
    const payload = {
      chasis_number: '',
      machine_number: '',
      color: '',
      plate_number: '',
      back_plate: '',
      stnk_use_ocr: false,
    }
    handleSaveDraft(payload, 1)
  }, [])

  const handleUseStnkData = useCallback(() => {
    setShowConflictBottomSheet(false)

    const year = Number(stnkOcrData?.year)
    const brandData = stnkOcrData?.brand_data
    const brandCode = brandData.code

    const regionData = stnkOcrData?.region_data
    const regionCode = regionData?.region_code

    const doResetStateRenewalToNewPurchase =
      draftQuotationsDetailsData?.policy_details?.renewal_status === MV_RENEWAL_STATUS.RENEWAL
    let renewalStatus = {}

    if (doResetStateRenewalToNewPurchase) {
      renewalStatus = {
        renewal_status: undefined,
        purchase_type: NEW_PURCHASE,
        purchase_renew_flow: undefined,
      }
    }

    const payload = {
      ...renewalStatus,
      year,
      brand: brandCode,
      brand_code: brandCode,
      brand_data: brandData,
      region_data: regionData,
      region_code: regionCode,
      model: undefined,
      model_data: undefined,
      stnk_url: '',
      chasis_number: '',
      machine_number: '',
      color: '',
      plate_number: '',
      back_plate: '',
      stnk_use_ocr: false,
    }
    handleSaveDraft(payload, 1)

    setIsBackToMVForm(true)
  }, [handleSaveDraft, stnkOcrData])
  // refetch get latest data
  useEffect(() => {
    if (updateDraftQuotationStatus === 'success') {
      getDraftQuoteDetailsReq({ draftQuoteId: that.current.draftQuoteId })
      if (isBackToMVForm) {
        history.push(`/motor_vehicle/v2/${that.current.draftQuoteId}`)
        setIsBackToMVForm(false)
      }
    }
  }, [updateDraftQuotationStatus, getDraftQuoteDetailsReq, isBackToMVForm])
  return (
    <Container
      title={LANG_STRINGS.mobil}
      loader={DRAFT_QUOTATIONS_DETAILS_LOADER || POST_DRAFT_POLICY_OCR_LOADER}
      className="bg-white"
      backBtnId="mobilPolicyFormStepBack_3"
      onClose={() => {
        history.replace('/dashboard')
        that.current.removeEvent && that.current.removeEvent()
        ShowSnackbar.success({ text: LANG_STRINGS.quotationSaveMsg })
      }}
      onSaveClick={handleSaveClick}
      saveLoader={UPDATE_DRAFT_QUOTATION_LOADER}
      disabledSave={!enableSave}
      showSaveIcon
      showCloseIcon
      hideBottomTabs
      hideGuardianInfo
      displayBackButton
    >
      <PolicyStepsHeader
        stepsData={POLICY_STEPS}
        activeCount={3}
        prevActive={{ 1: true, 2: true }}
      />
      <FixedTab iconUrl={CAR_ICON} text="Isi Data Kendaraan" />
      <MVVehicleFormStyle>
        {draftQuotationsDetailsData.policy_details && (
          <>
            <div className="" id="ssg-container">
              <section className="">
                <PageContainer>
                  <CustomText
                    color={AgentColorPallette.black}
                    size="1em"
                    top="1.2em"
                    bottom="0.5em"
                    weight={700}
                  >
                    {LANG_STRINGS.vehicleData}
                  </CustomText>
                  <VehicleDetails
                    key={render.toLocaleString()}
                    ref={vehicleDetailRef}
                    onChange={(data) => handleChanges(data, 'vehicle_detail_object')}
                    quoteData={draftQuotationsDetailsData.policy_details}
                    disabledFields={disabledFields}
                  />
                  <VehiclePhotos
                    ref={vehiclePhotosRef}
                    onChange={(data) => handleChanges(data, 'vehicle_photos')}
                    quoteData={draftQuotationsDetailsData.policy_details}
                  />
                  {!!draftQuotationsDetailsData?.policy_details.accessories?.length && (
                    <VehicleModificationPhotos
                      ref={vehicleModPhotosRef}
                      accessories={draftQuotationsDetailsData?.policy_details.accessories}
                      onChange={(data) => handleChanges(data, 'vehicle_modification_photos')}
                    />
                  )}
                  <VehicleDamageSection
                    ref={vehicleDamageRef}
                    damageData={{
                      damage_remarks: draftQuotationsDetailsData.policy_details.damage_remarks,
                      damage_photos: draftQuotationsDetailsData.policy_details.damage_photos,
                    }}
                    onChange={(data) => handleChanges(data, 'vehicle_damage')}
                  />
                </PageContainer>
              </section>
            </div>
            <ButtonContainer>
              <Button
                variant="filled"
                onClick={handleSubmit}
                disabled={hasValidationError || isChassisValidating}
              >
                {isChassisValidating ? 'Memvalidasi...' : 'Simpan & Lanjutkan'}
              </Button>
            </ButtonContainer>
          </>
        )}
      </MVVehicleFormStyle>
      <QuoteSaveConfirmModal
        show={showQuoteConfirm}
        onClose={() => setShowQuoteConfirm(false)}
        page={`${LANG_STRINGS.mobil} Step 3`}
        message={LANG_STRINGS.quotationSaveMsg}
      />
      <BottomSheetVehicleConflictData
        key={showConflictBottomSheet}
        show={showConflictBottomSheet}
        data={conflictData}
        onClose={() => setShowConflictBottomSheet(false)}
        onUseOldData={handleUseOldData}
        onUseStnkData={handleUseStnkData}
      />
    </Container>
  )
}

export default MVVehicleFormContainer
