import { VehicleDetailsStyle } from './index.style'
import DynamicForm from '../../../../../../../components/DynamicForm'
import { getVehicleDetailForm } from '../../constants'
import { forwardRef } from 'react'
import { useEffect } from 'react'
import { useState } from 'react'
import { isEmpty } from 'lodash/lang'

function VehicleDetails(
  { quoteData = {}, onChange = () => {}, disabledFields },
  vehicleDetailRef
) {
  const [rerender, setRerender] = useState(0)

  useEffect(() => {
    if (!isEmpty(quoteData)) {
      setRerender((prev) => prev + 1)
    }
  }, [quoteData])

  return (
    <VehicleDetailsStyle>
      <DynamicForm
        key={rerender.toString()}
        form={getVehicleDetailForm(quoteData, disabledFields)}
        ref={vehicleDetailRef}
        onChange={onChange}
        isValidateOnChange
        isDocSlider
      />
    </VehicleDetailsStyle>
  )
}

export default forwardRef(VehicleDetails)
