import { Grid } from '../../../../../../../commonStyle/index.style'
import { LANG_STRINGS } from '../../../../../../../lang'
import { VehicleDamageSectionStyle } from './index.style'
import CustomText from '../../../../../../../components/CustomText/index'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { useState, useCallback, forwardRef, useRef, useEffect } from 'react'
import DynamicForm from '../../../../../../../components/DynamicForm'
import { getVehicleCongenitalDamageFrom } from '../../constants'
import { isEmpty } from 'lodash/lang'
import { mappedUploadFileWithName } from '../../../../helpers'
import CustomCheckbox from '../../../../../../../components/CustomCheckbox'

function VehicleDamageSection ({ damageData = {}, onChange = () => {} }, vehicleDamageRef) {
  const [isVehicleDamage, setIsVehicleDamage] = useState(!!damageData.damage_remarks || !isEmpty(damageData?.damage_photos))
  const that = useRef({})

  const addEvenListener = useCallback((elem) => {
    elem.addEventListener('focusin', (e) => {
      that.current.isEventAdd = true
      e.preventDefault()
      e.stopPropagation()
    })
  }, [])

  useEffect(() => {
    const elm = document.getElementById('vehicleDamageSections')
    if (isVehicleDamage && !that.current.isEventAdd && elm) {
      addEvenListener(elm)
    }
  }, [addEvenListener, isVehicleDamage])

  const handleSwitch = useCallback(() => {
    setIsVehicleDamage(prevValue => !prevValue)
    addEvenListener(document.getElementById('vehicleDamageSections'))
  }, [addEvenListener])

  const handleChange = useCallback((data) => {
    const body = {
      ...data
    }
    if (data.damage_photos) {
      body.damage_photos = mappedUploadFileWithName(data.damage_photos)
    }
    onChange(body)
  }, [onChange])

  return (
    <VehicleDamageSectionStyle id='vehicleDamageSections'>
      <CustomText
        color={AgentColorPallette.black}
        size='1em'
        top='1.2em'
        bottom='0.5em'
        weight={700}
      >
        {LANG_STRINGS.vehicleDamage}
      </CustomText>
      <Grid
        gridColumn='10fr 1fr'
        gap='1rem'
        align='center'
        className='margin'
      >
        <CustomText
          color={AgentColorPallette.blackGrey}
          size='0.85rem'
        >
          {LANG_STRINGS.selectOptionIfVehicleHaveCongenitalDefect}
        </CustomText>
        <CustomCheckbox
          color={AgentColorPallette.black}
          isChecked={isVehicleDamage}
          onChange={handleSwitch}
        />
      </Grid>
      {
        isVehicleDamage && (
          <DynamicForm
            form={getVehicleCongenitalDamageFrom(damageData)}
            ref={vehicleDamageRef}
            onChange={handleChange}
            isDocSlider
          />
        )
      }
    </VehicleDamageSectionStyle>
  )
}

export default forwardRef(VehicleDamageSection)
