import React from 'react'
import { FixedTabContainer, ContentContainer, IconWrapper, TextWrapper, StepIndicator } from './index.style'

const FixedTab = ({ iconUrl, text, step = 1 }) => {
  return (
    <FixedTabContainer>
      <ContentContainer>
        <IconWrapper>
          <img src={iconUrl} alt='tab-icon' />
        </IconWrapper>
        <TextWrapper>
          {text}
        </TextWrapper>
        <StepIndicator>
          {step}/2
        </StepIndicator>
      </ContentContainer>
    </FixedTabContainer>
  )
}

export default FixedTab
