import { ADDRESS_ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action) => {
  const { type, payload = {} } = action
  switch (type) {
    case ADDRESS_ACTIONS.GET_PROVINCE_LIST:
    case ADDRESS_ACTIONS.GET_CITY_LIST:
    case ADDRESS_ACTIONS.VALIDATE_POSTAL_CODE:
      return {
        ...state,
        ...payload
      }
    default:
      return state
  }
}

export default reducer
