import { usePostDraftPolicyOcr } from '../../../state/hooks/usePolicyState'
import { useEffect, useState, useMemo, useRef } from 'react'
import { FILE_TYPE_OCR } from '../constants'
import {
  useErrorContextValue,
  useResetError,
} from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../../components/ShowNotification'

const FIELDS_TO_COMPARE = [
  {
    field: 'No. Rangka',
    draftValue: (data) => data?.chasis_number,
    ocrValue: (data) => data?.chassis_number,
    condition: (policyDetails) => policyDetails?.renewal_status === 'RENEWAL',
  },
  {
    field: 'Kode Area',
    draftValue: (data) => data?.region_code,
    ocrValue: (data) => data?.license_plate?.code_area,
  },
  {
    field: 'Brand',
    draftValue: (data) => data?.brand,
    ocrValue: (data) => data?.brand,
  },
  {
    field: 'Tahun',
    draftValue: (data) => data?.year,
    ocrValue: (data) => Number(data?.year),
  },
]

export const useOcrStnkService = ({
  draftId = '',
  handleSaveDraftStnk = () => {},
  handleErrorOcr = () => {},
  policyDetailData = {},
  setShowConflictModal = () => {},
  handleSaveDraftNotUseOcr = () => {},
}) => {
  const [lastProcessedStnkUrl, setLastProcessedStnkUrl] = useState(null)
  const [stnkOcrData, setStnkOcrData] = useState({})
  const [isOcrStnkComplete, setIsOcrStnkComplete] = useState(false)
  const [isOcrStnkError, setIsOcrStnkError] = useState(false)
  const processedOcrDataRef = useRef(null)
  const ocrDisabledFields = [
    'chasis_number',
    'machine_number',
    'color',
    'plate_number',
    'back_plate',
  ]

  const [{ postDraftPolicyOcrData }, postDraftPolicyOcrRequest] =
    usePostDraftPolicyOcr()
  const [{ postDraftPolicyOcrErrorData }] = useErrorContextValue()
  const { resetError } = useResetError()

  const handleStnkOcr = (stnkUrl) => {
    if (lastProcessedStnkUrl === stnkUrl) {
      return
    }

    setIsOcrStnkError(false)
    setIsOcrStnkComplete(false)
    processedOcrDataRef.current = null
    resetError(['postDraftPolicyOcrErrorData'])
    setStnkOcrData({})
    setLastProcessedStnkUrl(stnkUrl)
    postDraftPolicyOcrRequest({
      draftId,
      body: {
        document_url: stnkUrl,
        file_type: FILE_TYPE_OCR.STNK,
      },
    })
  }

  const checkOcrDataConflict = (
    policyDetails = policyDetailData,
    ocrData = stnkOcrData
  ) => {
    const conflicts = []

    FIELDS_TO_COMPARE.forEach((config) => {
      if (config.condition && !config.condition(policyDetails)) {
        return
      }

      const draftValue = config.draftValue(policyDetails)
      const ocrValue = config.ocrValue(ocrData)

      if (draftValue && ocrValue && draftValue !== ocrValue) {
        conflicts.push({
          field: config.field,
          oldValue: draftValue,
          stnkValue: ocrValue,
        })
      }
    })

    return conflicts
  }

  useEffect(() => {
    if (postDraftPolicyOcrData?.success) {
      if (postDraftPolicyOcrData?.data?.file_type === FILE_TYPE_OCR.STNK) {
        const ocrDataId = postDraftPolicyOcrData?.data?.document_url
        if (processedOcrDataRef.current !== ocrDataId) {
          processedOcrDataRef.current = ocrDataId
          setStnkOcrData(postDraftPolicyOcrData?.data)
          const conflict = checkOcrDataConflict(
            policyDetailData,
            postDraftPolicyOcrData?.data
          )
          if (conflict.length > 0) {
            setShowConflictModal(true)
            handleSaveDraftNotUseOcr()
          } else {
            handleSaveDraftStnk(postDraftPolicyOcrData?.data)
            setIsOcrStnkComplete(true)
          }
        }
      }
    }
  }, [postDraftPolicyOcrData?.data, postDraftPolicyOcrData?.success])

  useEffect(() => {
    if (!isOcrStnkError) {
      if (!postDraftPolicyOcrErrorData?.success) {
        // show error by type
        if (
          postDraftPolicyOcrErrorData?.data?.file_type === FILE_TYPE_OCR.STNK
        ) {
          handleErrorOcr(postDraftPolicyOcrErrorData)
          ShowSnackbar.error({
            text: postDraftPolicyOcrErrorData?.error,
          })
          setIsOcrStnkError(true)
        }
      }
    }
  }, [postDraftPolicyOcrErrorData?.success, handleErrorOcr, isOcrStnkError])

  const conflictData = useMemo(
    () => checkOcrDataConflict(policyDetailData, stnkOcrData),
    [policyDetailData, stnkOcrData]
  )

  return {
    handleStnkOcr,
    stnkOcrData,
    isOcrStnkComplete,
    ocrDisabledFields,
    conflictData,
  }
}
