import { forwardRef, useCallback, useRef } from 'react'
import { LANG_STRINGS } from '../../../../../../../lang/index'
import DynamicForm from '../../../../../../../components/DynamicForm'
import { getVehiclePhotos } from '../../constants'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { VehiclePhotosStyle } from './index.style'

function VehiclePhotos ({ quoteData = {}, onChange = () => {} }, vehiclePhotoRef) {
  const imgRef = useRef({
    ...(quoteData?.images || {})
  })

  const handleImgChange = useCallback((data) => {
    imgRef.current = {
      ...imgRef.current,
      ...data
    }
    onChange({
      images: { ...imgRef.current }
    })
  }, [onChange])

  return (
    <VehiclePhotosStyle>
      <CustomText
        color={AgentColorPallette.black}
        size='1em'
        top='1.2em'
        bottom='0.5em'
        weight={700}
      >
        {LANG_STRINGS.vehiclePhoto}
      </CustomText>
      <div className='vehicle-photos-section'>
        <DynamicForm
          form={getVehiclePhotos(quoteData)}
          ref={vehiclePhotoRef}
          onChange={handleImgChange}
        />
      </div>
    </VehiclePhotosStyle>
  )
}

export default forwardRef(VehiclePhotos)
