import _ from 'lodash'
import { useState, useCallback, useMemo, useEffect } from 'react'
import { createPortal } from 'react-dom'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { SEARCH, SELECTION_ARROW } from '../../../../images'
import { LANG_STRINGS } from '../../../../lang'
import BottomActionSheet from '../../../BottomActionSheet'
import Button from '../../../Button'
import { Error } from '../../../../commonStyle/index.style'
import usePopupApiOptions from './hooks/usePopupApiOptions'
import {
  StyleContainer,
  InputContainerStyle,
  PopupWrapperStyle,
  SearchBarStyle,
  ListStyle,
  ActionButtonWrapperStyle,
  PendingChipsStyle,
} from './index.styles'

function PopupApi({
  title,
  name,
  defaultValue,
  error,
  disabled = false,
  onChange = () => {},
  apiConfig = null,
  is_multiple = false,
  max_selected,
  is_searchable = false,
  option_section_title,
}) {
  const { options, isLoadingOptions } = usePopupApiOptions(apiConfig)

  const adaptedDefault = useMemo(() => {
    if (is_multiple !== true) return [defaultValue]
    return defaultValue || []
  }, [is_multiple, defaultValue])

  const [selected, setSelected] = useState(adaptedDefault)
  const [pending, setPending] = useState(adaptedDefault)
  const [show, setShow] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')

  const selectedChips = useMemo(
    () => selected.map((val) => options.find((o) => o.value === val)).filter(Boolean),
    [selected, options]
  )

  const pendingChips = useMemo(
    () => pending.map((val) => options.find((o) => o.value === val)).filter(Boolean),
    [pending, options]
  )

  useEffect(() => {
    setSelected(adaptedDefault)
    setPending(adaptedDefault)
  }, [adaptedDefault])

  const filteredOptions = useMemo(() => {
    if (!is_searchable || !searchQuery) return options
    const lq = searchQuery.toLowerCase()
    return options.filter((opt) => `${opt.label}`.toLowerCase().includes(lq))
  }, [options, searchQuery, is_searchable])

  const isLimitReached = useMemo(
    () => !_.isNil(max_selected) && pending.length >= max_selected,
    [pending, max_selected]
  )

  const addToPending = useCallback(
    (itemValue) => {
      if (isLimitReached) return
      setPending([...pending, itemValue])
    },
    [pending, isLimitReached]
  )

  const removeFromPending = useCallback(
    (itemValue) => {
      const next = pending.filter((v) => v !== itemValue)
      setPending(next)
    },
    [pending]
  )

  const handleClose = useCallback(() => {
    setShow(false)
    setSearchQuery('')
  }, [])

  const commitSelection = useCallback(
    (values) => {
      setSelected(values)
      setShow(false)
      setSearchQuery('')
      onChange({ name, value: is_multiple ? values : (values[0] ?? null) })
    },
    [name, onChange, is_multiple]
  )

  const handleSelect = useCallback(
    (itemValue) => {
      if (!is_multiple) {
        setPending([])
        commitSelection([itemValue])
        return
      }
      if (pending.includes(itemValue)) {
        removeFromPending(itemValue)
      } else {
        addToPending(itemValue)
      }
    },
    [is_multiple, pending, addToPending, removeFromPending, commitSelection]
  )

  const handleSave = useCallback(() => {
    commitSelection(pending)
  }, [pending, commitSelection])

  const handleRemoveSelectedChip = useCallback(
    (e, chipValue) => {
      e.stopPropagation()
      commitSelection(selected.filter((v) => v !== chipValue))
    },
    [selected, commitSelection]
  )

  return (
    <StyleContainer>
      <InputContainerStyle
        $compactTrigger={!is_multiple || selectedChips.length === 0}
        disabled={disabled}
        error={error}
        data-testid={`popup-api-trigger-${name}`}
        onClick={() => !disabled && setShow(true)}
      >
        <div className="select-content">
          <span className="field-label">{title}</span>
          {is_multiple && selectedChips.length > 0 && (
            <div className="chips-wrap">
              {selectedChips.map((chip) => (
                <div key={chip.value} className="chip">
                  {chip.label}
                  <span
                    className="chip-remove"
                    onClick={(e) => handleRemoveSelectedChip(e, chip.value)}
                  >
                    ✕
                  </span>
                </div>
              ))}
            </div>
          )}
          {!is_multiple && selectedChips[0]?.label != null && selectedChips[0].label !== '' && (
            <span className="selected-chip">{selectedChips[0].label}</span>
          )}
        </div>
        <img src={SELECTION_ARROW} alt="" />
      </InputContainerStyle>
      {error && <Error>{error}</Error>}

      {show &&
        createPortal(
          <BottomActionSheet
            show={show}
            onCloseSheet={handleClose}
            zIndex={100}
            showHeader
            headerTextAlign="left"
            title={title}
            titleStyle={{
              size: '12px',
              weight: 800,
              color: AgentColorPallette.darkCharcoal,
            }}
            backGroundColor={AgentColorPallette.primary}
          >
            <PopupWrapperStyle>
              {is_searchable && (
                <SearchBarStyle>
                  <input
                    className="search-input"
                    placeholder="Cari"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    data-testid="popup-api-search"
                  />
                  <img src={SEARCH} alt="search" className="search-icon" />
                </SearchBarStyle>
              )}

              <ListStyle>
                {option_section_title && (
                  <div className="section-title">{option_section_title}</div>
                )}
                {isLoadingOptions ? (
                  <div className="loading-state">Loading...</div>
                ) : filteredOptions.length === 0 ? (
                  <div className="empty-state">Tidak ada pilihan</div>
                ) : (
                  filteredOptions.map((opt) => {
                    const isPicked = pending.includes(opt.value)
                    const isDisabled = is_multiple && isLimitReached && !isPicked
                    return (
                      <div
                        key={opt.value}
                        className={`list-item ${isDisabled ? 'disabled' : ''}`}
                        data-testid={`popup-api-item-${opt.value}`}
                        onClick={() => handleSelect(opt.value)}
                      >
                        <div className="item-text">
                          <span className="item-label">{opt.label}</span>
                          {opt.description && (
                            <span className="item-description">{opt.description}</span>
                          )}
                        </div>
                        {is_multiple && (
                          <span className={`item-checkbox ${isPicked ? 'checked' : ''}`} />
                        )}
                      </div>
                    )
                  })
                )}
              </ListStyle>

              {is_multiple && (
                <ActionButtonWrapperStyle>
                  {is_multiple && pendingChips.length > 0 && (
                    <PendingChipsStyle>
                      {pendingChips.map((chip) => (
                        <div key={chip.value} className="selected-chip">
                          {chip.label}
                          <span
                            className="chip-remove"
                            onClick={() => removeFromPending(chip.value)}
                          >
                            ✕
                          </span>
                        </div>
                      ))}
                    </PendingChipsStyle>
                  )}

                  <div className="save-button">
                    <Button
                      data-testid="popup-api-pinned-save"
                      variant="filled"
                      handleClick={handleSave}
                    >
                      {LANG_STRINGS.saveNew}
                    </Button>
                  </div>
                </ActionButtonWrapperStyle>
              )}
            </PopupWrapperStyle>
          </BottomActionSheet>,
          document.getElementById('bottom-sheet-portal')
        )}
    </StyleContainer>
  )
}

export default PopupApi
