export const getDisabledFields = (renewalFlow) => {
  switch (renewalFlow) {
    case MV_RENEWAL_FLOW.EXISTING_CAR:
      return ['chasis_number']
    case MV_RENEWAL_FLOW.SHORTCUT:
      return ['chasis_number', 'machine_number', 'transmission_type']
    case MV_RENEWAL_FLOW.O2O:
      return []
    default:
      return []
  }
}

export const getVehicleDetailForm = (data = {}, disabledFields = []) => {
  return [
    {
      type: 'uploadFileV3',
      name: 'stnk_url',
      title: LANG_STRINGS.stnkPhoto,
      required: true,
      defaultValue: data?.stnk_url,
      disabled: disabledFields?.includes('stnk_url'),
      data: {
        fileType: INPUT_FILE_TYPE.IMAGE,
        showGuideBtn: true,
        guideData: STNK_GUIDE_TERMS,
      },
    },
    {
      type: 'inputV2',
      name: 'chasis_number',
      title: 'Nomor Rangka',
      required: true,
      defaultValue: data?.chasis_number,
      disabled: disabledFields?.includes('chasis_number'),
      regex_validation: regex.mvChasisNumber,
      errormsg: LANG_STRINGS.consist8to20CharactersChasisNumber,
      data: {
        subText: LANG_STRINGS.consist17Characters,
      },
    },
    {
      type: 'inputV2',
      name: 'machine_number',
      title: 'Nomor Mesin',
      required: true,
      defaultValue: data?.machine_number,
      disabled: disabledFields?.includes('machine_number'),
      regex_validation: regex.mvMachineNumber,
      errormsg: LANG_STRINGS.consist5to21CharactersMachineNumber,
      data: {
        subText: LANG_STRINGS.minimum9Characters,
      },
    },
    {
      type: 'radioV2',
      name: 'transmission_type',
      title: 'Transmisi',
      required: true,
      defaultValue: data?.transmission_type?.value || data?.transmission_type,
      disabled: disabledFields?.includes('transmission_type'),
      data: {
        options: [
          { value: 'Automatic', label: 'Otomatis' },
          { value: 'Manual', label: 'Manual' },
        ],
      },
    },
    {
      type: 'inputV2',
      name: 'color',
      title: 'Warna',
      required: true,
      disabled: disabledFields?.includes('color'),
      error: LANG_STRINGS.consist2to35CharactersVehicleColor,
      defaultValue: data?.color,
      placeholder: 'Warna',
    },
    {
      type: 'inputGrid',
      gridColumn: 3,
      gridType: ['inputV2', 'inputNumberV2', 'inputV2'],
      name: ['region_code', 'plate_number', 'back_plate'],
      title: ['Kode Plat', 'Nomor Plat', 'Kode Akhir'],
      required: [false, true, true],
      disabled: [
        true,
        disabledFields?.includes('plate_number'),
        disabledFields?.includes('back_plate'),
      ],
      defaultValue: [data?.region_code || '', data?.plate_number || '', data?.back_plate || ''],
      regex_validation: [null, regex.mvPlateNumber, regex.mvBackPlate],
      errormsg: [null, ERROR_LANG.maximum4digitsNumber, ERROR_LANG.maximum3charactersUpperCase],
      data: [{}, {}, { onlyLetters: true }],
    },
  ]
}

