export const getVehicleModificationForm = (data) => {
  return data.map((item, index) => {
    return {
      type: 'uploadFileV3',
      name: `accessory_img_${index}`,
      title: item.name,
      defaultValue: item.img,
      required: true,
      data: {
        showGuideBtn: true,
        guideData: DAMAGE_PHOTO_GUIDE,
      },
    }
  })
}

export const mapDamagePhotos = (damagePhotos) => {
  const mappedArr = []
  for (const key in damagePhotos) {
    mappedArr.push({
      filename: `image/${key}`,
      url: damagePhotos[key].original,
    })
  }

  return mappedArr
}

export const getVehicleCongenitalDamageFrom = (data = {}) => {
  return [
    {
      title: LANG_STRINGS.congenitalDamagePhoto,
      defaultValue: mapDamagePhotos(data?.damage_photos),
      name: 'damage_photos',
      type: 'uploadFileV3',
      required: true,
      data: {
        isMultiple: true,
        showGuideBtn: true,
        maxUpload: 10,
        guideData: DAMAGE_PHOTO_GUIDE,
      },
    },
    {
      type: 'inputV2',
      title: LANG_STRINGS.remarksSubmitted,
      name: 'damage_remarks',
      required: true,
      defaultValue: data?.damage_remarks,
    },
  ]
}

export const mappedVehicleDataToForm = (draftQuoteData = {}) => {
  const vehicleFormKeys = [
    'stnk_url',
    'chasis_number',
    'machine_number',
    'transmission_type',
    'color',
    'images',
    'vehicle_damage_url',
    'vehicle_damage_remarks',
  ]
  const mapped = {}
  vehicleFormKeys.forEach((key) => {
    if (draftQuoteData[key]) {
      mapped[key] = draftQuoteData[key]
    }
  })
  return mapped
}
