export const Label = styled.label`
  font-family: Roboto, Helvetica, Arial, sans-serif;
  letter-spacing: 0.00938em;
  padding: 0px;
  display: block;
  transform-origin: left top;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 24px);
  position: absolute;
  left: ${(props) => (props.active ? '2px' : '2px')};
  top: ${(props) => (props.active ? '-8px' : '8px')};
  transform: translate(14px, 16px) scale(1);
  transition:
    top 0.5s,
    font-size 0.5s,
    font-weight 0.5s,
    text-transform 0.5s,
    letter-spacing 0.5s,
    line-height 0.5s;
  z-index: 1;
  pointer-events: none;
  color: ${AgentColorPallette.fontGrey};

  /* Caption/Caption Medium */
  font-size: ${(props) => (props.active ? '8px' : '12px')};
  font-style: normal;
  font-weight: ${(props) => (props.active ? '800' : '500')};
  line-height: ${(props) => (props.active ? '10px' : '16px')};
  letter-spacing: ${(props) => (props.active ? '0.32px' : '')};
  text-transform: ${(props) => (props.active ? 'uppercase' : '')};
`
