import { useCallback, useRef } from 'react'
import { useHistory, useLocation } from 'react-router-dom'
import { MV_QUOTE_STEPS_SECTIONS } from '../../../constants/pkgCode'

export const useBackButton = (cb) => {
  // callback handle the path according to pages
  const history = useHistory()
  const location = useLocation()
  const eventHandler = useRef((currentData, handler) => {
    const prevStepsData = MV_QUOTE_STEPS_SECTIONS[currentData.section]
    let prevState = prevStepsData?.getPrevPath(currentData.draftId) || {}
    if (currentData.subSection === 'package_details') {
      prevState = prevStepsData?.getPrevPath('package_details', currentData.draftId)
    } else if (currentData.subSection === 'package_list') {
      prevState = prevStepsData?.getPrevPath('package_list', currentData.draftId)
    }
    window.removeEventListener('popstate', handler)
    if (prevState?.prevPath && prevState?.prevPath.includes(location?.state?.from)) {
      return
    }
    return history.push({
      pathname: prevState?.prevPath,
      state: {
        from: location.pathname,
        ...(prevState)
      }
    })
  })

  const addBackEventListener = useCallback((currentPage, cb) => {
    let isCbCalled = false
    const handler = () => {
      if (cb && !isCbCalled) {
        isCbCalled = true
        cb()
        return history.push({
          pathname: location.pathname
        })
      } else {
        eventHandler.current(currentPage, handler)
      }
    }
    window.addEventListener('popstate', handler)

    return () => {
      window.removeEventListener('popstate', handler)
    }
  }, [history, location])

  return addBackEventListener
}
