import moment from 'moment'

export const getMappedQuoteToPolicyData = (policy) => {
  const mappedObj = {
    ...policy,
    product: {
      ...policy.package_data
    },
    premium: {
      period: 12,
      amount: policy?.package_data?.basic_premium
    },
    total_bill: policy?.total_bill || policy?.package_data?.total_bill
  }
  delete mappedObj.package_data
  return mappedObj
}

export const mappedUploadFileWithName = (data = []) => {
  const mappedObj = {}
  data.forEach(item => {
    mappedObj[item.uuid] = {
      id: item.uuid,
      original: item.url,
      timestamp: moment().format('YYYY-MM-DD HH:MM')
    }
  })

  return mappedObj
}
